<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-0">Productos y stock</h2><span class="text-secondary">Productos vinculados a cada campaña.</span></div><a class="btn btn-primary text-white" href="index.php?c=producto&a=crear">+ Nuevo producto</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Producto</th><th>Campaña</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php if(!$productos):?><tr><td colspan="6" class="vacio">No hay productos cargados.</td></tr><?php else:foreach($productos as $p):?><tr><td><strong><?=e($p['nombre'])?></strong><small class="d-block text-secondary"><?=e($p['descripcion'])?></small></td><td><?=e($p['campania'])?></td><td>$<?=number_format($p['precio'],2,',','.')?></td><td><span class="badge text-bg-<?=$p['stock_actual']<=$p['stock_minimo']?'warning':'success'?>"><?=e($p['stock_actual'])?></span><small class="d-block">Mín. <?=e($p['stock_minimo'])?></small></td><td><?=$p['activo']?'Activo':'Inactivo'?></td><td><div class="acciones"><a class="btn btn-sm btn-outline-primary" href="index.php?c=producto&a=editar&id=<?=$p['id']?>">Editar</a><a class="btn btn-sm btn-outline-success" href="index.php?c=producto&a=ajustar&id=<?=$p['id']?>">Ajustar stock</a></div></td></tr><?php endforeach;endif;?></tbody></table></div></div></main><?php require __DIR__.'/../footer.php';?>
